use crate::aap::caps::inference_llm;

struct Node;

/// Upper bound on the `question` field (ensures: len(question) <= 512).
/// Counted in characters, so the result is also at most 512 bytes.
const MAX_QUESTION_CHARS: usize = 512;

/// Defensive bound on what is sent to the model. The `requires` clause already
/// guarantees the input is at most 4000 characters.
const MAX_PROMPT_CHARS: usize = 4000;

const SYSTEM: &str = "Classify the customer message into exactly one of these labels: \
billing_question, technical_support, account_change, general_inquiry. \
Reply with only the label. If no label fits, reply with: unknown.";

/// Map the model's reply onto the closed intent set. Anything outside the
/// known labels, including adversarial text, becomes `Unknown`.
fn parse_intent(raw: &str) -> Intent {
    let normalised = raw
        .trim()
        .trim_matches(|c: char| c == '"' || c == '\'' || c == '.' || c == '`')
        .trim()
        .to_ascii_lowercase();

    match normalised.as_str() {
        "billing_question" | "billing-question" => Intent::BillingQuestion,
        "technical_support" | "technical-support" => Intent::TechnicalSupport,
        "account_change" | "account-change" => Intent::AccountChange,
        "general_inquiry" | "general-inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

/// Bound the free-text residual to MAX_QUESTION_CHARS characters.
fn bounded(text: &str, max_chars: usize) -> String {
    text.chars().take(max_chars).collect()
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        let prompt = bounded(&message.text, MAX_PROMPT_CHARS);

        let reply = inference_llm::infer(SYSTEM, &prompt, "classify");
        let intent = parse_intent(&reply);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question: bounded(&message.text, MAX_QUESTION_CHARS),
        }
    }
}

export!(Node);
